def adaptar_reservas(apps, schema_editor):
    Reserva = apps.get_model('embarques', 'ReservaAssento')
    Ponto = apps.get_model('rotas', 'PontoEmbarque')
    banco = schema_editor.connection.alias
    Reserva.objects.using(banco).filter(sentido='retorno').update(trajeto='volta')
    # Reservas já vencidas continuam vencidas; a atualização não recupera vagas.
    for r in Reserva.objects.using(banco).filter(ativa=True, expira_em__gt=timezone.now()).select_related('viagem'):
        r.expira_em = timezone.make_aware(datetime.combine(r.viagem.data_servico+timedelta(days=1),time(3)))
        pontos = list(Ponto.objects.using(banco).filter(rota_id=r.viagem.rota_id,sentido=r.sentido,ativo=True)[:2])
        if len(pontos)==1:
            r.ponto_id=pontos[0].pk
        r.save(using=banco,update_fields=['expira_em','ponto'])


